import {
  runOrdinaryNotificationDispatch,
  type OrdinaryDispatchEnvironment,
} from "../../functions/lib/notifications/ordinary-dispatch.ts";
import sosNotificationWorker from "../sos-notification-delivery/index.ts";

// Generated by `wrangler pages functions build` earlier in the build pipeline.
// Keep the existing Pages Functions router as the HTTP handler; this entrypoint
// adds scheduled events without replacing or reimplementing its fetch routing.
// @ts-expect-error This generated module exists after build:worker runs.
import pagesFunctionsWorker from "../../dist/worker/index.js";

type Env = OrdinaryDispatchEnvironment;

export default {
  fetch: pagesFunctionsWorker.fetch,

  async scheduled(
    controller: ScheduledController,
    env: Env,
    context: ExecutionContext,
  ): Promise<void> {
    // Ordinary reminders are processed directly by sac-app. This removes the
    // old HTTP hop through the deleted Pages project.
    if (controller.cron === "* * * * *") {
      context.waitUntil(runOrdinaryNotificationDispatch(env.DB, env, Date.now()));
    }

    // Reuse the existing, tested SOS dispatch and hourly retention-purge
    // implementation. It selects the correct task from controller.cron.
    await sosNotificationWorker.scheduled(controller, env, context);
  },
};
